df['global_procedure_zscore_class'] = df['global_procedure_zscore'].apply(classify_zscore)

zscore_thresholds = {
    "Extreme Low Underuse" : (-float('inf'), -20),
    "Very Low Underuse" : (-20, -10),
    "Slightly Below Average Underuse" : (-10, -2),
    "Normal" : (-2, 1),
    "Mild Anomaly" : (1, 3),
    "Anomaly" : (3, 10),
    "Rare Anomaly" : (10, 20),
    "Extreme Anomaly" : (20, float('inf'))
    }

def classify_zscore(z):
    for category, (low, high) in zscore_thresholds.items():
        if low <= z < high:
            return category
    return "Normal"

df_merged['unusual_wait_time_class'] = df_merged.apply(assign_wait_time, axis=1)

def assign_wait_time(row):
    if row['PROC_CD'] == 'T2007':
        if 0 < row['QUANTITY_PAID'] <= 4:
            return 'Normal'
        elif 4 < row['QUANTITY_PAID'] <= 8:
            return 'High'
        elif 8 < row['QUANTITY_PAID'] <= 16:
            return 'Extremely High'
        elif 16 < row['QUANTITY_PAID'] <= 48:
            return 'Abnormal'
        elif row['QUANTITY_PAID'] > 48:
            return 'Suspicious'
    else:
        return 'No Wait Time'

provider_visit_counts['visit_frequency_class'] = provider_visit_counts['total_visit_frequency'].apply(flag_provider)

provider_visit_counts = provider_member_visits.groupby([provider_id, 'MEMBER_KEY'])['member_visit_frequency'].sum().reset_index(name='total_visit_frequency')

threshold_95 = provider_visit_counts['total_visit_frequency'].quantile(0.95)
threshold_98 = provider_visit_counts['total_visit_frequency'].quantile(0.98)
threshold_99 = provider_visit_counts['total_visit_frequency'].quantile(0.99)

def flag_provider(freq):
    if freq > threshold_99:
        return 'above 99th percentile'
    elif freq > threshold_98:
        return 'above 98th percentile'
    elif freq > threshold_95:
        return 'above 95th percentile'
    else:
        return 'below 95th percentile'

def proc_concentration(codes):
    counts = codes.value_counts(normalize=True)
    return float((counts**2).sum())
provider_features['proc_concentration_hhi'] = df.groupby(provider_id)['PROC_CD'].apply(proc_concentration)

def assign_quantity_percentile(group):
  if group['QUANTITY_PAID'].nunique() < 4:
    return pd.Series(['medium'] * len(group), index=group.index)
  quantiles = group['QUANTITY_PAID'].quantile([0.25, 0.5, 0.75, 0.99]).drop_duplicates().to_list()
  if len(quantiles) < 3:
    return pd.Series(['medium'] * len(group), index=group.index)

  # bins=[-np.inf] + quantiles + [np.inf]
  bins=[-np.inf] + quantiles[:3] + [np.inf]
  categories = ["low", "medium", "high", "very high", "extreme"]

  base_percentile = pd.cut(group['QUANTITY_PAID'], bins=bins, labels=categories[:-1])

  base_percentile = base_percentile.astype("object")

  extreme_threshold = quantiles[-1] # 99th percentile
  extreme_mask = group['QUANTITY_PAID'] >= extreme_threshold
  base_percentile[extreme_mask] = 'extreme'
  return base_percentile

df_bh['quantity_percentile'] = df_bh.groupby('proc_cd_category', group_keys=False).apply(assign_quantity_percentile)
